def run(g,bgc,mode,first_only=True):
    # mode: 'vert' = ray vertical through corner away from colarm; 'long' = along longer arm line through corner; 'both'=both rays
    bgc=Counter(v for r in g for v in r).most_common(1)[0][0]
    res=[r[:] for r in g]
    for c_ in set(v for r in g for v in r):
        if c_==bgc: continue
        for cells in compsof(g,c_):
            L=isL(cells)
            if not L: continue
            corner,colarm,rowarm=L
            rays=[]
            if mode in('vert','both'):
                below = corner[0] < colarm[-1][0] if colarm[0][0]<=corner[0] else corner[0] > colarm[0][0]
                # direction away from colarm: if arm extends down from corner, shoot up, else down
                down_arm = any(r2>corner[0] for r2,c2 in colarm)
                rays.append((0,-1) if down_arm else (0,1))
            if mode in('horiz','both'):
                right_arm = any(c2>corner[1] for r2,c2 in rowarm)
                rays.append((-1 if right_arm else 1,0))
            if mode=='long':
                if len(colarm)>=len(rowarm):
                    down_arm = any(r2>corner[0] for r2,c2 in colarm)
                    rays.append((0,-1) if down_arm else (0,1))
                else:
                    right_arm = any(c2>corner[1] for r2,c2 in rowarm)
                    rays.append((-1 if right_arm else 1,0))
            for (dx,dy) in rays:
                hits=shoot(g,corner,dx,dy,bgc,first_only)
                for (r,c) in hits:
                    if res[r][c]!=c_: res[r][c]=c_
    return res
