def linfo(comp):
    """If a component is an L (all cells in one column plus one row through a corner), return (corner, vertical_arm, horizontal_arm); else None."""
    for corner in comp:
        cr, cc = corner
        vert = [p for p in comp if p[1] == cc]
        hor = [p for p in comp if p[0] == cr]
        if set(vert) | set(hor) == set(comp):
